39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export interface ScenarioResults {
45	  results: (QuoteResult | ClaimResult)[];
46	}
47	
48	const sumBy = <T>(items: T[], amountOf: (item: T) => number): number =>
49	  items.reduce((total, item) => total + amountOf(item), 0);
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	} as const satisfies Record<string, number>;
62	
63	export type InsurableItemType = keyof typeof BASE_PREMIUMS;
64	
65	// The MHPCO's price list is the authority on what it will insure: a type it
66	// does not list cannot be quoted at all.
67	const basePremiumForType = (type: string): number => {
68	  const basePremium = BASE_PREMIUMS[type as InsurableItemType];
69	  if (basePremium === undefined) {
70	    throw new Error(`the MHPCO does not insure a ${type}`);
71	  }
72	  return basePremium;
73	};
74	
75	const BLOCK_SIZE = 3;
76	const BLOCK_PREMIUM = 60;
77	
78	// Items of one type, quoted together. A group of exactly 3 forms a building
79	// block and is offered at a flat base premium; any other size is priced per
80	// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
81	// groups, so neither is a block.
82	type AlikeGroup = [type: string, items: Item[]];
83	
84	const intoAlikeGroups = (items: Item[]): AlikeGroup[] => {
85	  const groups = new Map<string, Item[]>();
86	  for (const item of items) {
87	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
88	  }
89	  return [...groups];
90	};
91	
92	const isBuildingBlock = ([, items]: AlikeGroup): boolean =>
93	  items.length === BLOCK_SIZE;
94	
95	const basePremiumForGroup = (group: AlikeGroup): number => {
96	  const [type, items] = group;
97	  return isBuildingBlock(group)
98	    ? BLOCK_PREMIUM
99	    : items.length * basePremiumForType(type);
100	};
101	
102	const sumBasePremiums = (items: Item[]): number =>
103	  sumBy(intoAlikeGroups(items), basePremiumForGroup);
104	
105	const CURSE_SURCHARGE_RATE = 0.5;
106	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
107	const HIGH_ENCHANTMENT_THRESHOLD = 5;
108	
109	const isHighlyEnchanted = (item: Item): boolean =>
110	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
111	
112	// Item-specific modifiers apply to the base premium of the affected item, not
113	// to the policy total.
114	const surchargeRateForItem = (item: Item): number =>
115	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
116	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
117	
118	// Surcharges are charged against the item's own base premium, ignoring any
119	// building-block discount the item may be part of.
120	const surchargeForItem = (item: Item): number =>
121	  basePremiumForType(item.type) * surchargeRateForItem(item);
122	
123	const sumItemSurcharges = (items: Item[]): number =>
124	  sumBy(items, surchargeForItem);
125	
126	// Every amount is rounded in the MHPCO's favour, which cuts in opposite
127	// directions on either side of the ledger: a premium owed to the office rounds
128	// up, a payout owed by it rounds down. Only the final figure is rounded;
129	// intermediate amounts stay fractional.
130	const roundPremiumInMHPCOsFavour = Math.ceil;
131	const roundPayoutInMHPCOsFavour = Math.floor;
132	
133	const LOYALTY_DISCOUNT_RATE = 0.2;
134	const LOYALTY_YEARS_THRESHOLD = 2;
135	
136	const isLoyal = (customer: Customer): boolean =>
137	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
138	
139	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
140	
141	// Policy-wide modifiers are summed into one net rate, not compounded. The net
142	// is signed: a loyal customer's discount can outweigh the surcharge.
143	//
144	// The first insurance surcharge applies to every quote — each item in a quote
145	// is treated as a first insurance, regardless of customer history — so it is
146	// not cancelled by the follow-up contract discount.
147	const policyModifierRateFor = (
148	  customer: Customer,
149	  precedingContracts: number,
150	): number =>
151	  FIRST_INSURANCE_SURCHARGE_RATE -
152	  (isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
153	  (precedingContracts > 0 ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
154	
155	// Charged against the policy base premium — the sum of all item base premiums —
156	// and added to it, mirroring how surchargeForItem works per item.
157	const policyModifierFor = (
158	  basePremium: number,
159	  customer: Customer,
160	  precedingContracts: number,
161	): number => basePremium * policyModifierRateFor(customer, precedingContracts);
162	
163	const quotePremium = (
164	  items: Item[],
165	  customer: Customer,
166	  precedingContracts: number,
167	): number => {
168	  const basePremium = sumBasePremiums(items);
169	  const itemSurcharges = sumItemSurcharges(items);
170	  const policyModifier = policyModifierFor(
171	    basePremium,
172	    customer,
173	    precedingContracts,
174	  );
175	  return roundPremiumInMHPCOsFavour(
176	    basePremium + itemSurcharges + policyModifier + PROCESSING_FEE,
177	  );
178	};
179	
180	// An item's insured worth, distinct from what it costs to insure.
181	const INSURANCE_VALUES = {
182	  sword: 1000,
183	  amulet: 600,
184	  staff: 800,
185	  potion: 400,
186	  rune: 250,
187	  moonstone: 250,
188	} as const satisfies Record<InsurableItemType, number>;
189	
190	// Keyed off the price list rather than being an independent authority: the
191	// price list decides what is insurable, this table only says what an insurable
192	// item is worth. Reaching it with an uninsurable type means a quote was priced
193	// without being validated, which is a bug in the caller, not bad input — hence
194	// the distinct message.
195	const insuranceValueForType = (type: string): number => {
196	  const insuranceValue = INSURANCE_VALUES[type as InsurableItemType];
197	  if (insuranceValue === undefined) {
198	    throw new Error(`the MHPCO holds no insurance value for a ${type}`);
199	  }
200	  return insuranceValue;
201	};
202	
203	const DEDUCTIBLE = 100;
204	const CAP_MULTIPLE = 2;
205	
206	// A quote step creates a policy; later claim steps refer to it by that step's
207	// index. The cap is consumed as claims are paid.
208	interface Policy {
209	  items: Item[];
210	  remainingCap: number;
211	}
212	
213	// The policy's total insured worth.
214	const insuranceSumFor = (items: Item[]): number =>
215	  sumBy(items, (item) => insuranceValueForType(item.type));
216	
217	// The most the policy will ever pay out, derived from the plain item values.
218	// Nothing that moves the premium moves the cap: item surcharges cannot inflate
219	// it, and the building-block discount cannot deflate it.
220	const capFor = (items: Item[]): number =>
221	  CAP_MULTIPLE * insuranceSumFor(items);
222	
223	// The policy owns its item list: it is copied out of the step so that draining
224	// a claim's pool can never reach back into the caller's scenario.
225	const openPolicy = (items: Item[]): Policy => ({
226	  items: [...items],
227	  remainingCap: capFor(items),
228	});
229	
230	// Claims use their own, higher enchantment threshold — unrelated to the
231	// premium-side high-enchantment surcharge.
232	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
233	const HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
234	const FULL_REIMBURSEMENT_RATE = 1;
235	
236	const isHeavilyEnchanted = (item: Item): boolean =>
237	  (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
238	
239	// Damage to a heavily enchanted item is only half reimbursed.
240	//
241	// The spec's dragon-material clause is deliberately absent, not forgotten: it
242	// grants full reimbursement, which is already the default, and the heavy
243	// enchantment rule overrides it where both apply. No input exists for which
244	// reading `material` would change the payout, so a branch on it would be dead
245	// code. Reinstate one only if a rule makes dragon material differ from the
246	// default.
247	const reimbursementRateFor = (item: Item): number =>
248	  isHeavilyEnchanted(item)
249	    ? HEAVY_ENCHANTMENT_REIMBURSEMENT_RATE
250	    : FULL_REIMBURSEMENT_RATE;
251	
252	// Each damage entry is charged against one insured item, which no later entry
253	// may reuse — two sword damages need two insured swords. `unclaimed` is drained
254	// as entries are matched.
255	//
256	// This guard is also what rejects a damage entry naming a type the MHPCO does
257	// not insure at all. Such a type can never have reached a policy —
258	// basePremiumForType refuses it at quote time — so "not insured anywhere" is a
259	// strict subset of "not in this policy", and a separate unknown-type check here
260	// would be unreachable.
261	const claimInsuredItem = (unclaimed: Item[], damage: Damage): Item => {
262	  const at = unclaimed.findIndex((item) => item.type === damage.itemType);
263	  if (at === -1) {
264	    throw new Error(
265	      `the policy does not cover a ${damage.itemType} for this damage`,
266	    );
267	  }
268	  return unclaimed.splice(at, 1)[0];
269	};
270	
271	// A damage report describes harm done, so a negative amount is not a small
272	// claim but a malformed one.
273	const damageAmountOf = (damage: Damage): number => {
274	  if (damage.amount < 0) {
275	    throw new Error(
276	      `a ${damage.itemType} cannot be damaged by ${damage.amount} G`,
277	    );
278	  }
279	  return damage.amount;
280	};
281	
282	// The reimbursement rate applies to the damage first; the deductible comes off
283	// what remains, once per damage event rather than once per claim.
284	const payoutForDamage = (item: Item, damage: Damage): number =>
285	  damageAmountOf(damage) * reimbursementRateFor(item) - DEDUCTIBLE;
286	
287	// Settling a claim consumes the policy's cap, so the policy carries less cover
288	// into the next claim. Kept separate from settleClaim so the state change is
289	// visible where the policy is held rather than hidden behind a pure-looking call.
290	const consumeCap = (policy: Policy, result: ClaimResult): Policy => ({
291	  ...policy,
292	  remainingCap: result.remainingCap,
293	});
294	
295	const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
296	  const unclaimed = [...policy.items];
297	  // Per-damage amounts stay fractional; the claim total is rounded once, before
298	  // the cap is applied — rounding a capped figure would round the cap itself.
299	  const roundedClaimTotal = roundPayoutInMHPCOsFavour(
300	    sumBy(damages, (damage) =>
301	      payoutForDamage(claimInsuredItem(unclaimed, damage), damage),
302	    ),
303	  );
304	  // The cap limits what the policy will pay, so a claim beyond it is paid out
305	  // only as far as the cap reaches.
306	  const payout = Math.min(roundedClaimTotal, policy.remainingCap);
307	  return { payout, remainingCap: policy.remainingCap - payout };
308	};
309	
310	const runStep = (
311	  step: Step,
312	  customer: Customer,
313	  precedingContracts: number,
314	  policies: Map<number, Policy>,
315	  stepIndex: number,
316	): QuoteResult | ClaimResult => {
317	  switch (step.op) {
318	    case "quote":
319	      policies.set(stepIndex, openPolicy(step.items));
320	      return { premium: quotePremium(step.items, customer, precedingContracts) };
321	    case "claim": {
322	      const policy = policies.get(step.policy)!;
323	      const result = settleClaim(policy, step.incident.damages);
324	      policies.set(step.policy, consumeCap(policy, result));
325	      return result;
326	    }
327	  }
328	};
329	
330	// Each quote in a scenario forms a contract, so every quote after the first is
331	// a follow-up. Steps are run in order and a step sees only the contracts that
332	// precede it. Only quote steps create contracts.
333	export const runScenario = (scenario: Scenario): ScenarioResults => {
334	  const results: (QuoteResult | ClaimResult)[] = [];
335	  const policies = new Map<number, Policy>();
336	  let contractsSoFar = 0;
337	  scenario.steps.forEach((step, stepIndex) => {
338	    results.push(
339	      runStep(step, scenario.customer, contractsSoFar, policies, stepIndex),
340	    );
341	    if (step.op === "quote") contractsSoFar += 1;
342	  });
343	  return { results };
344	};
